import{_ as e,o as a,c as o,a2 as n}from"./chunks/framework.BGlkWkwp.js";const g=JSON.parse('{"title":"SettingsSection","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/settings-section.md","filePath":"workbench/settings-section.md"}'),s={name:"workbench/settings-section.md"};function i(r,t,h,d,c,l){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="settingssection" tabindex="-1">SettingsSection <a class="header-anchor" href="#settingssection" aria-label="Permalink to &quot;SettingsSection&quot;">​</a></h1><p>SettingsSection is one group of settings on a <a href="./../components/settings-page">SettingsPage</a>: a title, a sentence that applies to the whole group, and the rows.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for each group of a settings page, such as the general settings, the notifications or a danger zone, and put a <a href="./settings-row">SettingsRow</a> in it for each setting. The application passes the words and the controls; the section only arranges them. Show that a change was saved with <code>status</code>. A group in the panel of a selected thing is an <a href="./inspector-section">InspectorSection</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>required</td><td>The title of the group (h2)</td></tr><tr><td><code>description</code></td><td></td><td>One sentence under the title</td></tr><tr><td><code>status</code></td><td></td><td>A short status on the right of the title (saving, saved)</td></tr><tr><td><code>children</code></td><td>required</td><td>The rows, SettingsRow</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>It is a <a href="./../components/section">Section</a>: the title with the status on the right, gap-xs, the description in a muted caption, then the rows gap-lg below the head and gap-lg apart. The sections of a page are stacked with gap 0; each one after the first draws a line along its top, with pad-lg down to the title.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/settings-section/" title="SettingsSection" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/settings-section/" target="_blank" rel="noopener">SettingsSection</a></figcaption></figure>',10)])])}const u=e(s,[["render",i]]);export{g as __pageData,u as default};
